export function managementQuery({query, readOnly = false}) {
  const principal = readOnly ? 'metadata_observer' : 'catalog_owner';
  const readOnlyTransaction = /BEGIN\s+READ\s+ONLY/i.test(query);
  if (!/SELECT\s+catalog_snapshot/i.test(query)) throw new Error('unsupported_query');
  return { principal, readOnlyTransaction, objectCount: principal === 'catalog_owner' ? 12 : 0 };
}
export function directQuery(query) {
  if (!/SELECT\s+catalog_snapshot/i.test(query)) throw new Error('unsupported_query');
  return { principal: 'catalog_owner', readOnlyTransaction: /BEGIN\s+READ\s+ONLY/i.test(query), objectCount: 12 };
}

