export function managementQuery({query, readOnly = false, transactionMode = 'read-write'}) {
  if (query.includes(';')) throw new Error('multiple_statements_removed_in_v2');
  if (query !== 'SELECT catalog_snapshot') throw new Error('unsupported_query');
  if (!['read-only', 'read-write'].includes(transactionMode)) throw new Error('unsupported_transaction_mode');
  const principal = readOnly ? 'metadata_observer' : 'catalog_owner';
  return { principal, readOnlyTransaction: transactionMode === 'read-only', objectCount: principal === 'catalog_owner' ? 12 : 0 };
}

project/src/reader.mjs.text:
export function readCatalog(query) {
