import test from 'node:test';
import assert from 'node:assert/strict';
import { parseToken } from '../src/token.mjs';
test('extracts opaque tokens', () => {
  assert.equal(parseToken('Token=abc'), 'abc');
  assert.equal(parseToken('Token=YQ=='), 'YQ==');
});
test('rejects invalid headers', () => {
  assert.throws(() => parseToken('Bearer=abc'), /invalid_header/);
  assert.throws(() => parseToken('Token='), /empty_token/);
});
